def load() -> pd.DataFrame:
    import pandas as pd
    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Fraud, Identity Theft, and Other Reports by Military Consumers.csv"
    # Row 0 is blank; row 1 contains the true header.
    return pd.read_csv(path, header=1)

def process(fraudByMilitaryConsumers2024):
    import pandas as pd
    import re

    df = fraudByMilitaryConsumers2024.copy()

    # Promote first row to header
    df.columns = df.iloc[0].tolist()
    df = df.iloc[1:].reset_index(drop=True)

    # Keep only rows where Military Status is populated
    df['Military Status'] = df['Military Status'].astype(str).str.strip()

    # Candidate branch labels as they appear in this table
    branch_labels = [
        'U.S. Army', 'U.S. Navy', 'U.S. Air Force', 'U.S. Marines', 'U.S. Coast Guard', 'U.S. Space Force'
    ]
    branches = df[df['Military Status'].isin(branch_labels)].copy()

    def parse_money(x):
        if x is None or (isinstance(x, float) and pd.isna(x)):
            return pd.NA
        s = str(x).strip()
        if s == '' or s.lower() == 'none' or s.lower() == 'nan':
            return pd.NA
        s = re.sub(r'[^0-9,\.\-]', '', s)  # keep digits, comma, dot, minus
        s = s.replace(',', '')
        if s in ('', '-', '.', '-.'):
            return pd.NA
        try:
            return float(s)
        except Exception:
            return pd.NA

    branches['Median Fraud Loss (num)'] = branches['Median Fraud Loss'].apply(parse_money)
    branchesValid = branches.dropna(subset=['Median Fraud Loss (num)']).copy()

    if branchesValid.empty:
        # Diagnostics
        out = pd.DataFrame([{
            'error': 'No branch rows with numeric Median Fraud Loss after parsing',
            'branchRows': '; '.join(branches['Military Status'].astype(str).tolist()) if not branches.empty else '(no rows matched branch labels)',
            'medianValues': '; '.join(branches['Median Fraud Loss'].astype(str).tolist()) if not branches.empty else '(no rows matched branch labels)'
        }])
        return out

    maxRow = branchesValid.sort_values('Median Fraud Loss (num)', ascending=False).head(1)
    return maxRow[['Military Status', 'Median Fraud Loss', 'Median Fraud Loss (num)']].reset_index(drop=True)
